    40	func runProviderBackups() int {
    41		backupDir, exists := GetEnvOrFile(envGitBackupDir)
    42		if !exists || backupDir == "" {
    43			logger.Printf("environment variable %s is not set; skipping backup run", envGitBackupDir)
    44	
    45			return 0
    46		}
    47	
    48		if httpClient == nil {
    49			httpClient = getHTTPClient(os.Getenv(envSobaLogLevel))
    50		}
    51	
    52		workingDir := resolveWorkingDir(backupDir)
    53	
    54		// Cleanup runs on normal completion via this defer. Signal-driven
    55		// shutdown calls gocron's Shutdown() which waits for the current job to
    56		// finish, so this defer still fires before process exit on SIGINT/SIGTERM.
    57		defer cleanupWorkingDir(workingDir, backupDir)
    58	
    59		backupResults := BackupResults{
    60			StartedAt: sobaTime{
    61				Time: time.Now(),
    62				f:    time.RFC3339,
    63			},
    64		}
    65	
    66		providerBackupResults := collectProviderBackupResults(backupDir)
    67	
    68		backupResults.Results = &providerBackupResults
    69		backupResults.FinishedAt = sobaTime{
    70			Time: time.Now(),
    71			f:    time.RFC3339,
    72		}
    73	
    74		succeeded, failed := getBackupsStats(backupResults)
    75	
    76		switch {
    77		case succeeded == 0 && failed >= 0:
    78			logger.Println("all backups failed")
    79		case succeeded > 0 && failed > 0:
    80			logger.Println("backups completed with errors")
    81		default:
    82			logger.Println("backups complete")
    83		}
    84	
    85		notify(backupResults, succeeded, failed)
    86	
    87		if job != nil {
    88			nextRun, _ := job.NextRun()
    89			logger.Printf("next Run scheduled for: %s", nextRun.Format("2006-01-02 15:04:05 -0700 MST"))
    90		}
    91	
    92		return failed
    93	}
