   296	func getBackupInterval() int {
   297		backupIntervalEnv := os.Getenv(envGitBackupInterval)
   298	
   299		hours, isHour := isInt(backupIntervalEnv)
   300	
   301		switch {
   302		case isHour:
   303			// an int represents hours
   304			return hours * minutesPerHour
   305		case strings.HasSuffix(backupIntervalEnv, "h"):
   306			// a string ending in h represents hours
   307			hours, isHour = isInt(backupIntervalEnv[:len(backupIntervalEnv)-1])
   308			if isHour {
   309				return hours * minutesPerHour
   310			}
   311		case strings.HasSuffix(backupIntervalEnv, "m"):
   312			// a string ending in m represents minutes
   313			minutes, isMinute := isInt(backupIntervalEnv[:len(backupIntervalEnv)-1])
   314			if isMinute {
   315				return minutes
   316			}
   317		}
   318	
   319		return 0
   320	}
